function shotZoom(f){const sc=$('#shs'),c=$('#shc');if(!sc||!c)return;const r=sc.scrollTop/Math.max(1,sc.scrollHeight),rx=sc.scrollLeft/Math.max(1,sc.scrollWidth);shZ=f?Math.min(3,Math.max(.4,shZ*f)):1;const base=Math.min(sc.clientWidth-24,520);c.style.width=Math.round(base*shZ)+'px';const t=$('#shzp');if(t)t.textContent=Math.round(shZ*100)+'%';sc.scrollTop=r*sc.scrollHeight;sc.scrollLeft=rx*sc.scrollWidth}
