function shotPaint(cv,ctx0){cv=cv||$('#shv');if(!cv)return;const g=ctx0||cv.getContext('2d');g.clearRect(0,0,cv.width,cv.height);g.lineCap='round';g.lineJoin='round';for(const s of shSt){g.strokeStyle=s.c;g.lineWidth=s.w;g.beginPath();s.p.forEach((q,i)=>i?g.lineTo(q[0],q[1]):g.moveTo(q[0],q[1]));if(s.p.length==1)g.lineTo(s.p[0][0]+.1,s.p[0][1]);g.stroke()}}
