async function adThumbs(){const o=$('#adv');if(!o)return;for(const b of [...o.querySelectorAll('.adv-im .adv-t[data-k]')]){const k=b.dataset.k;if(!k||!$('#adv'))continue;try{const r=await api.mread({id:cur.id,u:k});if(!r||!r.ok)throw 0;const i=new Image();i.src=r.data;await i.decode();const z=Math.max(112/i.naturalWidth,112/i.naturalHeight),c=document.createElement('canvas');c.width=c.height=112;c.getContext('2d').drawImage(i,(112-i.naturalWidth*z)/2,(112-i.naturalHeight*z)/2,i.naturalWidth*z,i.naturalHeight*z);b.style.backgroundImage=`url(${c.toDataURL('image/jpeg',.72)})`}catch(e){b.classList.add('bad')}}}
