const TRD=30*864e5,trashL=()=>pages.filter(p=>p.trash),bkSize=n=>n>=1e9?(n/1e9).toFixed(1)+' GB':n>=1e6?(Math.round(n/1e5)/10)+' MB':Math.max(1,Math.round(n/1e3))+' KB';
function trashRow(){const e=$('#trb');if(!e)return;const n=trashL().length;e.innerHTML=n?`<button class=trl onclick=trashOpen()>🗑 Lixeira <b>${n}</b></button>`:''}
function trashDrop(id){const p=pages.find(x=>x.id==id);if(!p)return;if(!p.kind)api.mdel(id);SYNC.tomb(id);pages=pages.filter(x=>x.id!=id)}
function trFree(p){const had=!!(p.domain||p.path||p.dns);if(!had&&!p.addr)return'';const d=(p.domain||'')+(p.path?'/'+p.path:'');delete p.domain;delete p.path;delete p.addr;delete p.dns;return d}
function trashSweep(){let ch=0;pages.forEach(p=>{if(p.trash&&trFree(p))ch=1});if(ch)sv();const now=Date.now(),old=pages.filter(p=>p.trash&&now-p.trash>TRD&&p.trash<=now+864e5);if(!old.length)return;old.forEach(p=>trashDrop(p.id));sv()}
function trashRefresh(){const m=$('#trm');if(m)m.remove();if(view=='list')cards();else if(view=='fnl')fnList();if(trashL().length)trashOpen()}
function trashOpen(){trashSweep();const L=trashL().sort((a,b)=>b.trash-a.trash);if(!L.length){trashRow();return}const left=t=>Math.max(1,Math.ceil((TRD-(Date.now()-t))/864e5)),ago=t=>{const k=Math.floor((Date.now()-t)/864e5);return k<1?'hoje':k==1?'ontem':'há '+k+' dias'};
const o=modal('Lixeira',`<p class=mut style="margin:0 0 8px;font-size:12px">Os itens ficam aqui por 30 dias e depois somem de vez.</p><div class=trl2>${L.map(p=>`<div class=tri><div class=trn><b>${esc(p.name||'Sem nome')}</b><span>${p.kind=='funnel'?'Funil · ':''}apagado ${ago(p.trash)} · some em ${left(p.trash)} ${left(p.trash)==1?'dia':'dias'}</span></div><button class=b2 onclick="trashBack('${p.id}')">Recuperar</button><button class="b2 trx" onclick="trashKill('${p.id}')" title="Excluir para sempre" aria-label="Excluir para sempre">🗑</button></div>`).join('')}</div>`,[['Fechar',null,'b'],...(L.length>1?[['Esvaziar a lixeira',()=>trashAll()]]:[])]);o.id='trm'}
function trashBack(id){const p=pages.find(x=>x.id==id);if(!p)return;delete p.trash;sv();toast('Recuperado: '+(p.name||'Sem nome'));trashRefresh()}
async function trashKill(id){const p=pages.find(x=>x.id==id);if(!p)return;const f=p.kind=='funnel';if(!await askDel({tipo:f?'Funil':'Página',nome:p.name,thumb:f?'<span class=dl-ph>🔀</span>':thUrl(p)?`<img src="${thUrl(p)}" alt="">`:'<span class=dl-ph>🌐</span>',titulo:(f?'este funil':'esta página')+' será excluído'+(f?'':'a')+' para sempre',avisos:['Some deste aparelho e dos <b>outros aparelhos sincronizados</b>.',f?'As páginas que estavam nele não são apagadas.':'Se ela já foi publicada, a versão que está <b>no ar continua lá</b>.','Não dá para desfazer.']}))return;trashDrop(id);sv();trashRefresh()}
async function trashAll(){const L=trashL();if(!L.length)return;if(!await askDel({tipo:'Lixeira',nome:L.length+' itens',thumb:'<span class=dl-ph>🗑</span>',titulo:'a lixeira será esvaziada para sempre',avisos:['Tudo o que está nela some deste aparelho e dos <b>outros aparelhos sincronizados</b>.','O que já foi publicado continua no ar.','Não dá para desfazer.']}))return;L.forEach(p=>trashDrop(p.id));sv();trashRefresh()}
