function brgParse(t){const out=[],c=[];let m;const re=/```(?:json)?\s*([\s\S]*?)```/gi;while((m=re.exec(t)))c.push(m[1]);if(!c.length)c.push(t);for(const x of c){const s=x.trim();let v=null;try{v=JSON.parse(s)}catch{const i=s.search(/[\[{]/),j=Math.max(s.lastIndexOf(']'),s.lastIndexOf('}'));if(i>=0&&j>i){try{v=JSON.parse(s.slice(i,j+1))}catch{}}}if(v){if(!Array.isArray(v))v=Array.isArray(v.ops)?v.ops:[v];out.push(...v)}}return out}
function brgClean(o){if(!o||typeof o!='object')return null;const p=o.path,pv=Array.isArray(p)&&p.every(n=>Number.isInteger(n)&&n>=0),op=o.op;
if(op=='code'){const css=typeof o.css=='string'?o.css:'',js=typeof o.js=='string'?o.js:'';return css||js?{op,css,js}:null}
if(op=='style'){if(!pv||!o.props||typeof o.props!='object')return null;const pr={};for(const k in o.props){const v=o.props[k];if(v==null||typeof v=='object')continue;pr[k.replace(/[A-Z]/g,m=>'-'+m.toLowerCase())]=String(v)}return Object.keys(pr).length?{op,path:p,props:pr}:null}
if(op=='text')return pv&&typeof o.html=='string'?{op,path:p,html:o.html}:null;
if(op=='attr')return pv&&typeof o.k=='string'&&/^[\w:-]+$/.test(o.k)&&!/^on/i.test(o.k)&&(o.v==null||typeof o.v=='string'||typeof o.v=='number')?{op,path:p,k:o.k,v:o.v==null?null:String(o.v)}:null;
if(op=='ins'){if(typeof o.html!='string')return null;if(o.pos=='end')return{op,path:[],pos:'end',html:o.html};return pv&&p.length&&(o.pos=='after'||o.pos=='before')?{op,path:p,pos:o.pos,html:o.html}:null}
if(op=='rm')return pv&&p.length?{op,path:p}:null;return null}
function brgOpen(){const o=document.createElement('div');o.className='ov';o.innerHTML='<div class=md style="width:min(560px,92vw)"><h3>Aplicar resposta do Claude</h3><p class=mut style="margin:0 0 8px;font-size:13px">Cole a resposta do Claude (ou toque no campo e use Colar).</p><textarea id=brgt rows=10 style="width:100%;resize:vertical;font:12px/1.4 Consolas,monospace" placeholder="Cole aqui..."></textarea><p id=brge style="color:#ff8a8a;font-size:13px;margin:8px 0 0;min-height:18px"></p><div class=row><button class=b2 id=brgx>Cancelar</button><button class=b id=brgy>Aplicar na página</button></div></div>';document.body.append(o);const t=o.querySelector('#brgt'),e=o.querySelector('#brge');t.focus();t.addEventListener('paste',ev=>{try{const x=(ev.clipboardData||window.clipboardData).getData('text');ev.preventDefault();t.value=x;e.textContent=''}catch{}});try{navigator.clipboard.readText().then(x=>{if(x&&x!==brgLast&&!t.value&&(/\[\[\s*TROCAR/i.test(x)||/```/.test(x)||/"op"\s*:/.test(x)))t.value=x}).catch(()=>{})}catch{}o.querySelector('#brgx').onclick=()=>o.remove();
o.querySelector('#brgy').onclick=async()=>{brgLast=t.value;if(/\[\[\s*TROCAR\s*\]\]/i.test(t.value)){o.remove();return brgFull(t.value)}const raw=brgParse(t.value),ops=raw.map(brgClean).filter(Boolean);if(!ops.length){e.textContent=raw.length?'As alterações não estão no formato que o Shark Lab entende. Peça ao Claude: "responda de novo só com o bloco json no formato combinado".':'Não achei nenhuma alteração nesse texto. Confira se você copiou o bloco com as alterações.';return}
if(ops.some(x=>x.path&&x.path.length)&&brgN>=0&&cur.ops.length!=brgN&&!(await askC('Você mexeu na página depois de copiar para o Claude','As posições podem ter mudado. Aplicar mesmo assim?','Aplicar')))return;
o.remove();const r=await applyOps(ops);const skip=raw.length-ops.length;toast(r.ok?(r.ok+(r.ok==1?' alteração aplicada':' alterações aplicadas')+(r.fail||skip?'. '+((r.fail||0)+skip)+' não foram possíveis.':'. Confira como ficou.')):'Nenhuma alteração coube na página. Copie a página de novo e peça outra vez.')}}
/* ===== Página inteira: copiar o código e aplicar trocas (v55) ===== */
const BRG_FULL=['Você é o editor técnico da minha página de vendas. Abaixo está o CÓDIGO COMPLETO (HTML) dela. Eu peço uma mudança; você responde com 1 ou 2 frases dizendo o que fez e com os blocos de troca. Eu colo a resposta no Shark Lab e ele aplica sozinho.','','FORMATO (um bloco por troca; coloque todos dentro de UM bloco de código para eu copiar de uma vez):','[[TROCAR]]','trecho EXATO do código atual','[[POR]]','trecho novo','[[FIM]]','','REGRAS','- O trecho a trocar deve ser copiado EXATAMENTE do código, com linhas vizinhas suficientes para aparecer só UMA vez na página.','- Mude só o necessário. Nunca reescreva a página inteira nem devolva o código completo.','- Para ADICIONAR algo: troque uma linha-âncora por ela mesma mais o conteúdo novo.','- Para APAGAR: deixe vazio o que vem depois de [[POR]].','- Não mexa em links, botões de compra, pixels e scripts de rastreamento sem eu pedir.','- Trechos muito longos (imagens embutidas, scripts enormes) aparecem como ⟦SL#número⟧: não mexa neles.','- O código pode não mostrar as edições visuais que fiz no editor.','- Se o pedido não estiver claro, pergunte antes de responder.'].join('\n');
function brgShrink(h){const map=[],put=s=>{map.push(s);return'⟦SL#'+(map.length-1)+'⟧'};
h=h.replace(/data:[a-z0-9.+\/-]+;base64,[A-Za-z0-9+\/=]{200,}/gi,m=>put(m));
for(const tg of['script','style']){let out='',i=0;const lo=h.toLowerCase();while(true){const s=lo.indexOf('<'+tg,i);if(s<0){out+=h.slice(i);break}const g=lo.indexOf('>',s);if(g<0){out+=h.slice(i);break}const e=lo.indexOf('</'+tg,g);if(e<0){out+=h.slice(i);break}const body=h.slice(g+1,e);if(body.length>20000){out+=h.slice(i,g+1)+put(body);i=e}else{out+=h.slice(i,e);i=e}}h=out}
return{h,map}}
const brgExpand=(s,map)=>String(s).replace(/⟦SL#(\d+)⟧/g,(m,i)=>map&&map[+i]!=null?map[+i]:m);
function brgFindAll(h,a){const res=[];let i=-1;while((i=h.indexOf(a,i+1))>=0){res.push([i,i+a.length]);if(res.length>20)break}if(res.length)return res;
const s=a.trim();if(!s)return[];let pat=s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&').replace(/\/>/g,'\\s*\\/?>').replace(/>\s+</g,'>\\s*<').replace(/\s+/g,'\\s+');let re;try{re=new RegExp(pat,'gi')}catch{return[]}let m;while((m=re.exec(h))){res.push([m.index,m.index+m[0].length]);if(res.length>20)break;if(m[0].length==0)re.lastIndex++}return res}
function brgParseFull(t){const cut=s=>s.replace(/^[ \t]*\r?\n/,'').replace(/\r?\n[ \t]*$/,''),out=[],re=/\[\[\s*TROCAR\s*\]\]([\s\S]*?)\[\[\s*POR\s*\]\]([\s\S]*?)\[\[\s*FIM\s*\]\]/gi;let m;while((m=re.exec(t)))out.push({a:cut(m[1]),b:cut(m[2])});return out}
function brgPlan(html,blocks,map){let h=html;const rows=[];for(const b of blocks){const a=brgExpand(b.a,map),n=brgExpand(b.b,map),m=a.trim()?brgFindAll(h,a):[];let st='ok';if(!a.trim())st='vazio';else if(!m.length)st='nao';else if(m.length>1)st='varios';const bi=h.search(/<body[\s>]/i);rows.push({a,n,st,body:st=='ok'&&bi>=0&&m[0][0]>bi});if(st=='ok')h=h.slice(0,m[0][0])+n+h.slice(m[0][1])}const n=rows.filter(r=>r.st=='ok').length;return{rows,h,n,ok:n>0&&n==rows.length}}

